"use client";

import { useEffect, useState } from "react";
import { doc, getDoc, setDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/context/AuthContext";
import { Plus, X, Save } from "lucide-react";

interface GlobalSettings {
  leadStages: string[];
  investorTypes: string[];
}

export default function SettingsPage() {
  const { profile } = useAuth();
  const [settings, setSettings] = useState<GlobalSettings>({ leadStages: [], investorTypes: [] });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [newStage, setNewStage] = useState("");
  const [newType, setNewType] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const isAdmin = profile?.role === "admin";

  useEffect(() => {
    async function fetchSettings() {
      try {
        const docRef = doc(db, "settings", "global");
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          setSettings(docSnap.data() as GlobalSettings);
        } else {
          // Initialize default settings if none exist
          const defaultSettings: GlobalSettings = {
            leadStages: ["New", "Contacted", "Pitch/Meeting", "Due Diligence", "Committed", "Closed Won", "Closed Lost"],
            investorTypes: ["Institutional", "Family Office", "HNWI", "Retail", "Corporate"]
          };
          await setDoc(docRef, defaultSettings);
          setSettings(defaultSettings);
        }
      } catch (err) {
        console.error("Error fetching settings:", err);
        setError("Failed to load settings.");
      } finally {
        setLoading(false);
      }
    }
    fetchSettings();
  }, []);

  const handleSave = async () => {
    if (!isAdmin) return;
    setSaving(true);
    setError("");
    setSuccess("");
    try {
      await setDoc(doc(db, "settings", "global"), settings);
      setSuccess("Settings saved successfully.");
      setTimeout(() => setSuccess(""), 3000);
    } catch (err: any) {
      setError(err.message || "Failed to save settings");
    } finally {
      setSaving(false);
    }
  };

  const addStage = () => {
    if (newStage.trim() && !settings.leadStages.includes(newStage.trim())) {
      setSettings(prev => ({ ...prev, leadStages: [...prev.leadStages, newStage.trim()] }));
      setNewStage("");
    }
  };

  const removeStage = (stage: string) => {
    setSettings(prev => ({ ...prev, leadStages: prev.leadStages.filter(s => s !== stage) }));
  };

  const addType = () => {
    if (newType.trim() && !settings.investorTypes.includes(newType.trim())) {
      setSettings(prev => ({ ...prev, investorTypes: [...prev.investorTypes, newType.trim()] }));
      setNewType("");
    }
  };

  const removeType = (type: string) => {
    setSettings(prev => ({ ...prev, investorTypes: prev.investorTypes.filter(t => t !== type) }));
  };

  if (loading) return <div className="p-8 animate-pulse text-slate-500">Loading settings...</div>;

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <div className="mb-8 flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">System Settings</h1>
          <p className="text-slate-500 mt-1">Configure global CRM parameters like pipeline stages.</p>
        </div>
        {isAdmin && (
          <button 
            onClick={handleSave}
            disabled={saving}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-md font-medium transition-colors disabled:opacity-50"
          >
            <Save className="w-4 h-4" />
            {saving ? "Saving..." : "Save Changes"}
          </button>
        )}
      </div>

      {error && <div className="mb-6 p-4 bg-red-50 text-red-700 rounded-md text-sm border border-red-100">{error}</div>}
      {success && <div className="mb-6 p-4 bg-green-50 text-green-700 rounded-md text-sm border border-green-100">{success}</div>}

      {!isAdmin && (
        <div className="mb-6 p-4 bg-amber-50 text-amber-800 rounded-md text-sm border border-amber-200">
          <strong>Read-Only Mode:</strong> Only Administrators can modify system settings.
        </div>
      )}

      <div className="space-y-8">
        {/* Pipeline Stages Section */}
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-6 border-b border-slate-100">
            <h2 className="text-lg font-semibold text-slate-900">Pipeline Stages</h2>
            <p className="text-sm text-slate-500 mt-1">Define the steps in your capital raising process.</p>
          </div>
          <div className="p-6">
            <div className="flex flex-wrap gap-2 mb-6">
              {settings.leadStages.map((stage) => (
                <div key={stage} className="flex items-center gap-2 bg-slate-100 text-slate-700 px-3 py-1.5 rounded-md text-sm font-medium">
                  {stage}
                  {isAdmin && (
                    <button onClick={() => removeStage(stage)} className="text-slate-400 hover:text-red-500 transition-colors">
                      <X className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>
              ))}
            </div>
            {isAdmin && (
              <div className="flex items-center gap-3">
                <input 
                  type="text" 
                  value={newStage}
                  onChange={(e) => setNewStage(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && addStage()}
                  placeholder="e.g. Soft Circle" 
                  className="flex-1 max-w-xs px-3 py-2 border border-slate-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                <button 
                  onClick={addStage}
                  className="flex items-center gap-1 text-sm font-medium text-blue-600 hover:text-blue-700"
                >
                  <Plus className="w-4 h-4" /> Add Stage
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Investor Types Section */}
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-6 border-b border-slate-100">
            <h2 className="text-lg font-semibold text-slate-900">Investor Types</h2>
            <p className="text-sm text-slate-500 mt-1">Categorize the entities you are raising capital from.</p>
          </div>
          <div className="p-6">
            <div className="flex flex-wrap gap-2 mb-6">
              {settings.investorTypes.map((type) => (
                <div key={type} className="flex items-center gap-2 bg-blue-50 text-blue-700 px-3 py-1.5 rounded-md text-sm font-medium">
                  {type}
                  {isAdmin && (
                    <button onClick={() => removeType(type)} className="text-blue-400 hover:text-red-500 transition-colors">
                      <X className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>
              ))}
            </div>
            {isAdmin && (
              <div className="flex items-center gap-3">
                <input 
                  type="text" 
                  value={newType}
                  onChange={(e) => setNewType(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && addType()}
                  placeholder="e.g. Wealth Manager" 
                  className="flex-1 max-w-xs px-3 py-2 border border-slate-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                <button 
                  onClick={addType}
                  className="flex items-center gap-1 text-sm font-medium text-blue-600 hover:text-blue-700"
                >
                  <Plus className="w-4 h-4" /> Add Type
                </button>
              </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  signInWithPopup,
  GoogleAuthProvider,
  RecaptchaVerifier,
  signInWithPhoneNumber,
  ConfirmationResult
} from "firebase/auth";
import { auth } from "@/lib/firebase";
import { useRouter } from "next/navigation";

export default function LoginPage() {
  const [isLogin, setIsLogin] = useState(true);
  const [authMethod, setAuthMethod] = useState<"email" | "phone">("email");

  // Email/Pass State
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  // Phone Auth State
  const [phoneNumber, setPhoneNumber] = useState("");
  const [verificationCode, setVerificationCode] = useState("");
  const [confirmationResult, setConfirmationResult] = useState<ConfirmationResult | null>(null);

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  useEffect(() => {
    // Cleanup recaptcha if component unmounts
    return () => {
      if ((window as any).recaptchaVerifier) {
        (window as any).recaptchaVerifier.clear();
      }
    };
  }, []);

  const handleEmailSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      if (isLogin) {
        await signInWithEmailAndPassword(auth, email, password);
      } else {
        await createUserWithEmailAndPassword(auth, email, password);
      }
      router.push("/dashboard");
    } catch (err: any) {
      setError(err.message || "Authentication failed");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    setError("");
    setLoading(true);
    try {
      const provider = new GoogleAuthProvider();
      await signInWithPopup(auth, provider);
      router.push("/dashboard");
    } catch (err: any) {
      setError(err.message || "Google sign-in failed");
    } finally {
      setLoading(false);
    }
  };

  const setupRecaptcha = () => {
    if (!(window as any).recaptchaVerifier) {
      (window as any).recaptchaVerifier = new RecaptchaVerifier(auth, 'recaptcha-container', {
        size: 'invisible'
      });
    }
  };

  const handleSendCode = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    setupRecaptcha();

    try {
      const appVerifier = (window as any).recaptchaVerifier;
      const confirmation = await signInWithPhoneNumber(auth, phoneNumber, appVerifier);
      setConfirmationResult(confirmation);
    } catch (err: any) {
      setError(err.message || "Failed to send code");
      if ((window as any).recaptchaVerifier) {
        (window as any).recaptchaVerifier.render().then((widgetId: any) => {
          (window as any).grecaptcha.reset(widgetId);
        });
      }
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyCode = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!confirmationResult) return;

    setError("");
    setLoading(true);
    try {
      await confirmationResult.confirm(verificationCode);
      router.push("/dashboard");
    } catch (err: any) {
      setError(err.message || "Invalid verification code");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full space-y-8 bg-white p-10 rounded-xl shadow-sm border border-slate-200">
        <div>
          <h2 className="mt-2 text-center text-3xl font-extrabold text-slate-900">
