                <th className="px-6 py-4">Organization</th>
                <th className="px-6 py-4">Investor Type</th>
                <th className="px-6 py-4">Lead Stage</th>
                <th className="px-6 py-4">Last Interaction</th>
                <th className="px-6 py-4">Follow-up Date</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan={8} className="px-6 py-8 text-center text-slate-500">Loading leads...</td>
                </tr>
              ) : leads.length === 0 ? (
                <tr>
                  <td colSpan={8} className="px-6 py-12 text-center text-slate-500">
                    No leads yet. Click "New Lead" to add your first one.
                  </td>
