                      <button className="text-blue-600 hover:text-blue-800 font-medium text-sm">View</button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <AddLeadModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSuccess={fetchLeads} 
      />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { collection, query, where, getDocs, doc, getDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/context/AuthContext";
import { format } from "date-fns";
import { Building2, Calendar, User } from "lucide-react";

export default function PipelinePage() {
  const { user, profile } = useAuth();
  const [stages, setStages] = useState<string[]>([]);
  const [leadsByStage, setLeadsByStage] = useState<Record<string, any[]>>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchData() {
      if (!user || !profile) return;

      try {
        // 1. Fetch Global Settings for Stages
        const settingsSnap = await getDoc(doc(db, "settings", "global"));
        let activeStages = ["New", "Contacted", "Closed Won"]; // Fallback
        if (settingsSnap.exists() && settingsSnap.data().leadStages) {
          activeStages = settingsSnap.data().leadStages;
        }
        setStages(activeStages);

        // 2. Fetch Leads (with RBAC)
        let q = collection(db, "leads");
        if (profile.role === "junior") {
          q = query(q, where("primaryOwner", "==", user.uid));
        }

        const querySnapshot = await getDocs(q);
        const allLeads = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

        // 3. Group Leads by Stage
        const grouped: Record<string, any[]> = {};
        activeStages.forEach(s => { grouped[s] = []; }); // Init empty arrays

        allLeads.forEach(lead => {
          const stage = lead.leadStage || "New";
          if (!grouped[stage]) grouped[stage] = [];
          grouped[stage].push(lead);
        });

        setLeadsByStage(grouped);
      } catch (err) {
        console.error("Failed to load pipeline data:", err);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, [user, profile]);

  if (loading) return <div className="p-8 text-slate-500 animate-pulse">Loading pipeline...</div>;

  return (
    <div className="p-8 h-full flex flex-col">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Pipeline</h1>
        <p className="text-slate-500 mt-1">Manage and track deals across all stages.</p>
      </div>

      <div className="flex-1 flex gap-6 overflow-x-auto pb-4">
        {stages.map(stage => {
          const columnLeads = leadsByStage[stage] || [];

          return (
            <div key={stage} className="flex-shrink-0 w-80 flex flex-col bg-slate-100 rounded-xl max-h-full">
              <div className="p-4 flex items-center justify-between border-b border-slate-200">
                <h3 className="font-semibold text-slate-700">{stage}</h3>
                <span className="bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-xs font-medium">
                  {columnLeads.length}
                </span>
              </div>

              <div className="flex-1 p-3 overflow-y-auto space-y-3">
                {columnLeads.map(lead => (
                  <div key={lead.id} className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 hover:border-blue-300 transition-colors cursor-pointer">
                    <div className="flex justify-between items-start mb-2">
                      <h4 className="font-semibold text-slate-900">{lead.firstName} {lead.lastName}</h4>
                      <span className="text-[10px] uppercase font-bold text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded">
                        {lead.investorType}
                      </span>
                    </div>

                    <div className="space-y-2 mt-3">
                      <div className="flex items-center text-xs text-slate-500">
                        <Building2 className="w-3.5 h-3.5 mr-2 text-slate-400" />
                        {lead.organization || "No organization"}
                      </div>

                      {lead.followUpDate && (
                        <div className="flex items-center text-xs text-slate-500">
                          <Calendar className="w-3.5 h-3.5 mr-2 text-slate-400" />
                          Follow-up: {format(lead.followUpDate.toDate(), "MMM d, yyyy")}
                        </div>
                      )}
                    </div>
                  </div>
                ))}

                {columnLeads.length === 0 && (
                  <div className="text-center p-4 text-sm text-slate-400 border-2 border-dashed border-slate-200 rounded-lg">
                    No leads in this stage
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

