"use client";

import { useEffect, useState } from "react";
import { collection, query, where, getDocs } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/context/AuthContext";
import { format, isBefore, isSameDay, startOfDay } from "date-fns";
import { Calendar } from "lucide-react";

export default function FollowUpsPage() {
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(true);

  const [overdue, setOverdue] = useState<any[]>([]);
  const [today, setToday] = useState<any[]>([]);
  const [upcoming, setUpcoming] = useState<any[]>([]);

  useEffect(() => {
    async function fetchFollowUps() {
      if (!user || !profile) return;
      try {
        let q = collection(db, "leads");
        if (profile.role === "junior") {
          q = query(q, where("primaryOwner", "==", user.uid));
        }

        const snapshot = await getDocs(q);
        const leads = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }))
          .filter(lead => lead.followUpDate); // Must have a date

        const now = startOfDay(new Date());

        const _overdue: any[] = [];
        const _today: any[] = [];
        const _upcoming: any[] = [];

        leads.forEach(lead => {
          const date = lead.followUpDate.toDate();
          const targetDay = startOfDay(date);

          if (isSameDay(targetDay, now)) {
            _today.push(lead);
          } else if (isBefore(targetDay, now)) {
            _overdue.push(lead);
          } else {
            _upcoming.push(lead);
          }
        });

        setOverdue(_overdue.sort((a, b) => a.followUpDate.toMillis() - b.followUpDate.toMillis()));
        setToday(_today);
        setUpcoming(_upcoming.sort((a, b) => a.followUpDate.toMillis() - b.followUpDate.toMillis()));

      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    fetchFollowUps();
  }, [user, profile]);

  if (loading) return <div className="p-8 animate-pulse text-slate-500">Loading follow-ups...</div>;

  const renderSection = (title: string, count: number, items: any[], colorClass: string) => (
    <div className={`bg-white rounded-xl border ${colorClass} shadow-sm overflow-hidden`}>
      <div className="p-4 border-b border-slate-100 flex items-center gap-3">
        <h3 className="font-semibold text-slate-900">{title}</h3>
        <span className="bg-slate-100 text-slate-600 px-2 py-0.5 rounded-full text-xs font-medium">{count}</span>
      </div>
      <div className="p-2">
        {items.length === 0 ? (
          <div className="p-6 text-center text-sm text-slate-400">Nothing here.</div>
        ) : (
          <div className="divide-y divide-slate-100">
            {items.map(lead => (
              <div key={lead.id} className="p-4 hover:bg-slate-50 transition-colors flex justify-between items-center">
                <div>
                  <p className="font-medium text-slate-900">{lead.firstName} {lead.lastName}</p>
                  <p className="text-xs text-slate-500 mt-1">{lead.organization}</p>
                </div>
                <div className="text-right">
                  <div className="inline-flex items-center text-xs text-slate-500 bg-slate-100 px-2 py-1 rounded">
                    <Calendar className="w-3 h-3 mr-1.5" />
                    {format(lead.followUpDate.toDate(), "MMM d, yyyy")}
                  </div>
                  <p className="text-xs text-blue-600 mt-1 cursor-pointer hover:underline">View Lead</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="p-8 max-w-4xl mx-auto flex flex-col h-full">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-slate-900">Follow-ups</h1>
        <p className="text-sm text-slate-500 mt-1">Auto-populated from the "Follow-up Date" field on your Leads.</p>
      </div>

      <div className="space-y-6">
        {renderSection("Overdue", overdue.length, overdue, "border-red-200")}
        {renderSection("Today", today.length, today, "border-slate-200")}
        {renderSection("Upcoming", upcoming.length, upcoming, "border-slate-200")}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { collection, query, getDocs, addDoc, Timestamp, doc, getDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/context/AuthContext";
import { Mail, Send, Users } from "lucide-react";

export default function EmailPage() {
  const { user } = useAuth();
  const [stages, setStages] = useState<string[]>([]);
  const [selectedStage, setSelectedStage] = useState<string>("All");

  const [subject, setSubject] = useState("");
  const [body, setBody] = useState("");

  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("");

  useEffect(() => {
    async function fetchStages() {
      const snap = await getDoc(doc(db, "settings", "global"));
      if (snap.exists() && snap.data().leadStages) {
        setStages(snap.data().leadStages);
      }
    }
    fetchStages();
  }, []);

  const handleQueueEmails = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    setLoading(true);
    setStatus("");

    try {
      // 1. Fetch matching leads
      const q = query(collection(db, "leads"));
      const snapshot = await getDocs(q);
      let targetLeads = snapshot.docs.map(d => ({ id: d.id, ...d.data() }));

      if (selectedStage !== "All") {
        targetLeads = targetLeads.filter(l => l.leadStage === selectedStage);
      }

      const leadsWithEmail = targetLeads.filter(l => l.email);

      if (leadsWithEmail.length === 0) {
        setStatus("No leads found with valid email addresses for this criteria.");
        setLoading(false);
        return;
      }

      // 2. Queue emails
      const batchPromises = leadsWithEmail.map(lead => {
        // Simple variable replacement
        const personalizedBody = body.replace(/{{firstName}}/gi, lead.firstName || "Investor");

        return addDoc(collection(db, "email_queue"), {
          recipientEmail: lead.email,
          recipientName: `${lead.firstName || ''} ${lead.lastName || ''}`.trim(),
          leadId: lead.id,
          subject,
          body: personalizedBody,
          status: "pending",
          queuedBy: user.uid,
          createdAt: Timestamp.now()
        });
      });

      await Promise.all(batchPromises);
      setStatus(`Successfully queued ${batchPromises.length} emails. They will be processed in batches.`);
      setSubject("");
      setBody("");
    } catch (err: any) {
      console.error(err);
      setStatus("Failed to queue emails: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-8 max-w-4xl mx-auto flex flex-col h-full">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-slate-900">Email Campaigns</h1>
        <p className="text-sm text-slate-500 mt-1">Send bulk emails to your investors using Brevo integration.</p>
      </div>

      <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
        {status && (
          <div className={`p-4 mb-6 text-sm rounded-md ${status.includes('Failed') || status.includes('No leads') ? 'bg-amber-50 text-amber-800 border border-amber-200' : 'bg-green-50 text-green-800 border border-green-200'}`}>
            {status}
          </div>
        )}

        <form onSubmit={handleQueueEmails} className="space-y-6">
          <div>
            <label className="flex items-center gap-2 text-sm font-medium text-slate-700 mb-2">
              <Users className="w-4 h-4 text-slate-400" /> Target Audience (Pipeline Stage)
            </label>
            <select 
              value={selectedStage} 
              onChange={e => setSelectedStage(e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md text-sm focus:ring-blue-500 focus:border-blue-500"
            >
              <option value="All">All Leads</option>
              {stages.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
            <p className="text-xs text-slate-500 mt-1">Only leads with valid email addresses will be targeted.</p>
          </div>

          <div className="pt-4 border-t border-slate-100">
            <label className="flex items-center gap-2 text-sm font-medium text-slate-700 mb-2">
              <Mail className="w-4 h-4 text-slate-400" /> Email Subject
            </label>
            <input 
              type="text" 
              required
              value={subject}
              onChange={e => setSubject(e.target.value)}
              placeholder="e.g. Q3 Fund Performance Update"
              className="w-full px-3 py-2 border border-slate-300 rounded-md text-sm focus:ring-blue-500 focus:border-blue-500"
            />
          </div>

          <div>
            <div className="flex justify-between items-end mb-2">
              <label className="text-sm font-medium text-slate-700">Email Body</label>
              <span className="text-xs text-blue-600 bg-blue-50 px-2 py-1 rounded">Tip: Use {"{{firstName}}"} for personalization</span>
            </div>
            <textarea 
              required
              rows={8}
              value={body}
              onChange={e => setBody(e.target.value)}
              placeholder="Hi {{firstName}},&#10;&#10;I wanted to share our latest prospectus..."
              className="w-full px-3 py-2 border border-slate-300 rounded-md text-sm focus:ring-blue-500 focus:border-blue-500"
            />
          </div>

          <div className="flex justify-end pt-4">
            <button 
              type="submit" 
              disabled={loading}
              className="flex items-center gap-2 px-6 py-2.5 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 disabled:opacity-50"
            >
              <Send className="w-4 h-4" />
              {loading ? "Queueing..." : "Queue Campaign"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

