// Sub-component for Team Management
import { collection, getDocs, updateDoc } from "firebase/firestore";

function TeamManager() {
  const [users, setUsers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchUsers() {
      try {
        const snap = await getDocs(collection(db, "users"));
        setUsers(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
      } catch (err) {
        console.error("Failed to load users", err);
      } finally {
        setLoading(false);
      }
    }
    fetchUsers();
  }, []);

  const changeRole = async (uid: string, newRole: string) => {
    try {
      await updateDoc(doc(db, "users", uid), { role: newRole });
      setUsers(users.map(u => u.uid === uid ? { ...u, role: newRole } : u));
    } catch (err) {
      alert("Failed to update role");
    }
  };

  if (loading) return <div className="p-6 text-sm text-slate-500">Loading team...</div>;

  return (
    <table className="w-full text-left text-sm whitespace-nowrap">
      <thead className="bg-slate-50 border-b border-slate-200 text-slate-500 text-xs font-semibold">
        <tr>
          <th className="px-6 py-3">Email</th>
          <th className="px-6 py-3">Role</th>
        </tr>
      </thead>
      <tbody className="divide-y divide-slate-100">
        {users.map(u => (
          <tr key={u.uid} className="hover:bg-slate-50">
            <td className="px-6 py-3 text-slate-900 font-medium">{u.email}</td>
            <td className="px-6 py-3">
              <select 
                value={u.role || "junior"} 
                onChange={(e) => changeRole(u.uid, e.target.value)}
                className="px-2 py-1 text-xs border border-slate-300 rounded-md bg-white focus:ring-blue-500"
              >
                <option value="admin">Admin</option>
                <option value="senior">Senior</option>
                <option value="junior">Junior</option>
              </select>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

