"use client";

import { useEffect, useState, useRef } from "react";
import { collection, query, where, getDocs, addDoc, Timestamp } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/context/AuthContext";
import { AddLeadModal } from "@/components/leads/AddLeadModal";
import { Plus, Search, Filter, Download, Upload, LayoutGrid } from "lucide-react";
import { format } from "date-fns";

export default function LeadsPage() {
  const { user, profile } = useAuth();
  const [leads, setLeads] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [error, setError] = useState("");

  // Columns state
  const [showColsMenu, setShowColsMenu] = useState(false);
  const [cols, setCols] = useState({
    org: true,
    type: true,
    stage: true,
    interaction: true,
    followup: true
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchLeads = async () => {
    if (!user || !profile) return;
    setLoading(true);
    try {
      let q: any = collection(db, "leads");
      if (profile.role === "junior") {
        q = query(q, where("primaryOwner", "==", user.uid));
      }
      const querySnapshot = await getDocs(q);
      const leadsData: any[] = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setLeads(leadsData);
    } catch (err: any) {
      setError("Failed to load leads.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLeads();
  }, [user, profile]);

  // Export Logic
  const handleExport = () => {
    const headers = ["First Name", "Last Name", "Organization", "Email", "Investor Type", "Lead Stage"];
    const csvContent = [
      headers.join(","),
      ...leads.map(l => [
        `"${l.firstName || ''}"`, 
        `"${l.lastName || ''}"`, 
        `"${l.organization || ''}"`, 
        `"${l.email || ''}"`, 
        `"${l.investorType || ''}"`, 
        `"${l.leadStage || ''}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `leads_export_${format(new Date(), 'yyyy-MM-dd')}.csv`;
    a.click();
  };

  // Import Logic
  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n');

        // Skip header (i=1)
        for (let i = 1; i < lines.length; i++) {
          if (!lines[i].trim()) continue;
          // Simple split (ignores commas in quotes for this MVP)
          const [firstName, lastName, organization, email, investorType, leadStage] = lines[i].split(',').map(s => s.replace(/"/g, '').trim());

          await addDoc(collection(db, "leads"), {
            firstName: firstName || "",
            lastName: lastName || "",
            organization: organization || "Imported Org",
            email: email || "",
            investorType: investorType || "Unknown",
            leadStage: leadStage || "New",
            lastInteraction: Timestamp.now(),
            primaryOwner: user?.uid,
            createdAt: Timestamp.now(),
          });
        }
        await fetchLeads(); // Refresh table
        alert("Import successful!");
      } catch (err) {
        alert("Failed to parse or import CSV.");
      }
    };
    reader.readAsText(file);
    // Reset file input
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  return (
    <div className="p-8 max-w-7xl mx-auto flex flex-col h-full">
      {/* Header Actions */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Leads</h1>
          <p className="text-sm text-slate-500 mt-1">{leads.length} of {leads.length} leads</p>
        </div>
        <div className="flex items-center gap-3 relative">

