"use client";

import { useEffect, useState, useRef } from "react";
import { collection, query, where, getDocs, addDoc, Timestamp } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/context/AuthContext";
import { AddLeadModal } from "@/components/leads/AddLeadModal";
import { Plus, Search, Filter, Download, Upload, LayoutGrid, ArrowUp, ArrowDown, EyeOff, Eye } from "lucide-react";
import { format } from "date-fns";

type ColumnDef = { id: string; label: string; visible: boolean };

export default function LeadsPage() {
  const { user, profile } = useAuth();
  const [leads, setLeads] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [error, setError] = useState("");

  const [showColsMenu, setShowColsMenu] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [columns, setColumns] = useState<ColumnDef[]>([
    { id: 'firstName', label: 'First Name', visible: true },
    { id: 'org', label: 'Organization', visible: true },
    { id: 'type', label: 'Investor Type', visible: true },
    { id: 'stage', label: 'Lead Stage', visible: true },
    { id: 'interaction', label: 'Last Interaction', visible: true },
    { id: 'followup', label: 'Follow-up Date', visible: true },
    { id: 'owner', label: 'Primary Owner', visible: true },
    { id: 'lastName', label: 'Last Name', visible: false },
    { id: 'country', label: 'Current Country', visible: false },
  ]);

  const fetchLeads = async () => {
    if (!user || !profile) return;
    setLoading(true);
    try {
      let q: any = collection(db, "leads");
      if (profile.role === "junior") {
        q = query(q, where("primaryOwner", "==", user.uid));
      }
      const querySnapshot = await getDocs(q);
      const leadsData: any[] = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setLeads(leadsData);
    } catch (err: any) {
      setError("Failed to load leads.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLeads();
  }, [user, profile]);

  // Export Logic
  const handleExport = () => {
    const visibleCols = columns.filter(c => c.visible);
    const headers = visibleCols.map(c => c.label);
    const csvContent = [
      headers.join(","),
      ...leads.map(l => visibleCols.map(c => `"${getCellValue(l, c.id) || ''}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `leads_export_${format(new Date(), 'yyyy-MM-dd')}.csv`;
    a.click();
  };

  // Import Logic
  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n');
        for (let i = 1; i < lines.length; i++) {
          if (!lines[i].trim()) continue;
          const [firstName, lastName, organization, email, investorType, leadStage] = lines[i].split(',').map(s => s.replace(/"/g, '').trim());
          await addDoc(collection(db, "leads"), {
            firstName: firstName || "",
            lastName: lastName || "",
            organization: organization || "Imported Org",
            email: email || "",
            investorType: investorType || "Unknown",
            leadStage: leadStage || "New",
            lastInteraction: Timestamp.now(),
            primaryOwner: user?.uid,
            createdAt: Timestamp.now(),
          });
        }
        await fetchLeads();
        alert("Import successful!");
      } catch (err) {
        alert("Failed to parse or import CSV.");
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  // Column Reordering Logic
  const moveColumn = (index: number, direction: 'up' | 'down') => {
    const newCols = [...columns];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex >= 0 && targetIndex < newCols.length && newCols[targetIndex].visible === newCols[index].visible) {
      [newCols[index], newCols[targetIndex]] = [newCols[targetIndex], newCols[index]];
      setColumns(newCols);
    }
  };

  const toggleColumn = (id: string) => {
    setColumns(columns.map(c => c.id === id ? { ...c, visible: !c.visible } : c));
  };

  const getCellValue = (lead: any, colId: string) => {
    switch(colId) {
      case 'firstName': return lead.firstName;
      case 'lastName': return lead.lastName;
      case 'org': return lead.organization;
      case 'type': return lead.investorType;
      case 'stage': return lead.leadStage;
      case 'interaction': return lead.lastInteraction ? format(lead.lastInteraction.toDate(), "MMM d, yyyy") : "-";
      case 'followup': return lead.followUpDate ? format(lead.followUpDate.toDate(), "MMM d, yyyy") : "-";
      case 'owner': return lead.primaryOwner === user?.uid ? "Me" : "Other User";
      case 'country': return lead.country || "-";
      default: return "";
    }
  };

  const renderCell = (lead: any, colId: string) => {
    const val = getCellValue(lead, colId);
    if (colId === 'type') {
      return <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-blue-50 text-blue-700">{val}</span>;
    }
    if (colId === 'stage') {
      return <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-slate-100 text-slate-700">{val}</span>;
    }
    return <span className="text-slate-600">{val}</span>;
  };

  return (
    <div className="p-8 max-w-7xl mx-auto flex flex-col h-full">
      {/* Header Actions */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Leads</h1>
          <p className="text-sm text-slate-500 mt-1">{leads.length} of {leads.length} leads</p>
        </div>
        <div className="flex items-center gap-3 relative">

          <button onClick={handleExport} className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-md hover:bg-slate-50">
            <Download className="w-4 h-4" /> Export
          </button>

          <input type="file" accept=".csv" ref={fileInputRef} onChange={handleImport} className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-md hover:bg-slate-50">
            <Upload className="w-4 h-4" /> Import
          </button>

          <div className="relative">
            <button 
              onClick={() => setShowColsMenu(!showColsMenu)}
              className="flex items-center gap-2 px-4 py-1.5 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-md hover:bg-slate-50"
            >
              <LayoutGrid className="w-4 h-4" /> Columns
            </button>

            {showColsMenu && (
              <div className="absolute right-0 top-full mt-2 w-72 bg-white border border-slate-200 rounded-lg shadow-xl z-20 py-2">
                <div className="px-4 py-2">
                  <h4 className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider mb-2">Visible Columns (Drag to reorder)</h4>
                  <div className="space-y-1">
                    {columns.map((c, i) => c.visible && (
                      <div key={c.id} className="flex items-center justify-between group hover:bg-slate-50 px-2 py-1.5 rounded-md">
                        <div className="flex items-center gap-2">
                          <div className="flex flex-col text-slate-300 group-hover:text-slate-500">
                            <button onClick={() => moveColumn(i, 'up')} className="hover:text-slate-900"><ArrowUp className="w-3 h-3" /></button>
                            <button onClick={() => moveColumn(i, 'down')} className="hover:text-slate-900"><ArrowDown className="w-3 h-3" /></button>
                          </div>
                          <span className="text-sm font-medium text-slate-700">{c.label}</span>
                        </div>
                        <button onClick={() => toggleColumn(c.id)} className="text-slate-400 hover:text-slate-600">
                          <EyeOff className="w-4 h-4" />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="border-t border-slate-100 mt-2 pt-2 px-4 pb-2">
                  <h4 className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider mb-2">Hidden Columns</h4>
                  <div className="space-y-1">
                    {columns.map(c => !c.visible && (
                      <div key={c.id} className="flex items-center gap-2 hover:bg-slate-50 px-2 py-1.5 rounded-md text-slate-500">
                        <button onClick={() => toggleColumn(c.id)} className="text-slate-400 hover:text-blue-600">
                          <Eye className="w-4 h-4" />
                        </button>
                        <span className="text-sm">{c.label}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>

          <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center gap-2 px-4 py-1.5 text-sm font-medium text-white bg-slate-900 rounded-md hover:bg-slate-800"
          >
            <Plus className="w-4 h-4" /> New Lead
          </button>
        </div>
      </div>

      {/* Toolbar */}
      <div className="flex items-center gap-3 mb-6">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
          <input 
            type="text" 
            placeholder="Search name, organization, email, notes..." 
            className="w-full pl-9 pr-4 py-2 border border-slate-200 rounded-md text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
          />
        </div>
        <button className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 rounded-md hover:bg-slate-50">
          <Filter className="w-4 h-4" /> Filter
        </button>
      </div>

      {error && (
        <div className="p-4 mb-4 text-sm text-red-700 bg-red-100 rounded-md">
          {error}
        </div>
      )}

      {/* Table */}
      <div className="bg-white border border-slate-200 rounded-xl shadow-sm flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm whitespace-nowrap">
            <thead className="bg-slate-50 border-b border-slate-200 text-slate-500 text-xs font-semibold">
              <tr>
                <th className="px-6 py-4 w-10">
                  <input type="checkbox" className="rounded border-slate-300 text-blue-600 focus:ring-blue-500" />
                </th>
                {columns.filter(c => c.visible).map(c => (
                  <th key={c.id} className="px-6 py-4">{c.label}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan={columns.filter(c => c.visible).length + 1} className="px-6 py-8 text-center text-slate-500">Loading leads...</td>
                </tr>
              ) : leads.length === 0 ? (
                <tr>
                  <td colSpan={columns.filter(c => c.visible).length + 1} className="px-6 py-12 text-center text-slate-500">
                    No leads yet. Import a CSV or click "New Lead".
                  </td>
                </tr>
              ) : (
                leads.map((lead) => (
                  <tr key={lead.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <input type="checkbox" className="rounded border-slate-300 text-blue-600 focus:ring-blue-500" />
                    </td>
                    {columns.filter(c => c.visible).map(c => (
                      <td key={c.id} className="px-6 py-4">
                        {renderCell(lead, c.id)}
                      </td>
                    ))}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <AddLeadModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSuccess={fetchLeads} 
      />
    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { collection, getDocs, addDoc, Timestamp } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/context/AuthContext";
import { 
  Mail, Send, CheckCircle2, Eye, MousePointerClick, AlertCircle, 
  Settings2, Plus, X, Search, Filter
} from "lucide-react";

type ViewState = 'dashboard' | 'compose';

export default function EmailModule() {
  const { user } = useAuth();
  const [view, setView] = useState<ViewState>('dashboard');

  // Data State
  const [leads, setLeads] = useState<any[]>([]);
  const [settings, setSettings] = useState<any>({ leadStages: [], investorTypes: [] });

  // Compose State
  const [campaignName, setCampaignName] = useState("");
  const [sender, setSender] = useState("Money Stories IR <ir@moneystories.in>");
  const [subject, setSubject] = useState("");
  const [body, setBody] = useState("<p>Dear {{first_name}},</p>\n\n<p>We are pleased to share our latest fund performance update regarding <strong>{{organization}}</strong>.</p>\n\n<p>Warm regards,<br>The Team</p>");
  const [bodyMode, setBodyMode] = useState<'source' | 'rendered'>('source');

  // Filter State
  const [stageFilter, setStageFilter] = useState("All Stages");
  const [typeFilter, setTypeFilter] = useState("All Types");
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedLeads, setSelectedLeads] = useState<Set<string>>(new Set());

  const bodyRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    async function fetchData() {
      try {
        const [leadsSnap, settingsSnap] = await Promise.all([
          getDocs(collection(db, "leads")),
          getDocs(collection(db, "settings"))
        ]);

        setLeads(leadsSnap.docs.map(d => ({ id: d.id, ...d.data() })));

        const globalSettings = settingsSnap.docs.find(d => d.id === 'global')?.data();
        if (globalSettings) {
          setSettings(globalSettings);
        }
      } catch (err) {
        console.error("Failed to fetch data for email module", err);
      }
    }
    fetchData();
  }, []);

  // Filter Logic
  const filteredLeads = leads.filter(lead => {
    const matchesStage = stageFilter === "All Stages" || lead.leadStage === stageFilter;
    const matchesType = typeFilter === "All Types" || lead.investorType === typeFilter;
    const matchesSearch = !searchQuery || 
      `${lead.firstName} ${lead.lastName} ${lead.email} ${lead.organization}`
      .toLowerCase().includes(searchQuery.toLowerCase());
    return matchesStage && matchesType && matchesSearch;
  });

  const handleSelectAll = () => {
    if (selectedLeads.size === filteredLeads.length) {
      setSelectedLeads(new Set());
    } else {
      setSelectedLeads(new Set(filteredLeads.map(l => l.id)));
    }
  };

  const toggleLead = (id: string) => {
    const newSet = new Set(selectedLeads);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedLeads(newSet);
  };

  const insertTag = (tag: string) => {
    if (bodyRef.current) {
      const start = bodyRef.current.selectionStart;
      const end = bodyRef.current.selectionEnd;
      const newBody = body.substring(0, start) + tag + body.substring(end);
      setBody(newBody);

      // Reset cursor focus after state update hack
      setTimeout(() => {
        if (bodyRef.current) {
          bodyRef.current.focus();
          bodyRef.current.setSelectionRange(start + tag.length, start + tag.length);
        }
      }, 0);
    } else {
      setBody(prev => prev + tag);
    }
  };

  const sendCampaign = async () => {
    if (selectedLeads.size === 0) return alert("Select at least 1 recipient.");
    if (!subject || !body || !campaignName) return alert("Fill in all campaign details.");

    try {
      await addDoc(collection(db, "email_queue"), {
        campaignName,
        sender,
        subject,
        bodyTemplate: body,
        recipientIds: Array.from(selectedLeads),
        status: "queued",
        createdAt: Timestamp.now(),
        createdBy: user?.uid
      });
      alert(`Campaign "${campaignName}" queued for ${selectedLeads.size} recipients!`);
      setView('dashboard');
      // Reset compose state
      setCampaignName("");
      setSubject("");
      setSelectedLeads(new Set());
    } catch (err) {
      alert("Failed to queue campaign");
    }
  };

  const tags = [
    { tag: "{{first_name}}", label: "First Name" },
    { tag: "{{last_name}}", label: "Last Name" },
    { tag: "{{organization}}", label: "Organization" },
    { tag: "{{email}}", label: "Email" },
    { tag: "{{investor_type}}", label: "Investor Type" },
    { tag: "{{lead_stage}}", label: "Lead Stage" },
    { tag: "{{current_country}}", label: "Country" },
  ];

  return (
    <div className="p-8 max-w-6xl mx-auto">
      {view === 'dashboard' ? (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
          {/* Header */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-slate-900">Email Campaigns & Broadcasts</h1>
              <span className="px-2.5 py-0.5 rounded-md border border-slate-200 text-xs font-medium text-slate-600 bg-white">
                Brevo Engine
              </span>
            </div>
            <div className="flex gap-3">
              <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-md font-medium text-sm hover:bg-slate-50 transition-colors shadow-sm">
                <Settings2 className="w-4 h-4" /> Brevo Config
              </button>
              <button 
                onClick={() => setView('compose')}
                className="flex items-center gap-2 px-4 py-2 bg-[#1a1a1a] text-white rounded-md font-medium text-sm hover:bg-black transition-colors shadow-sm"
              >
                <Plus className="w-4 h-4" /> New Campaign
              </button>
            </div>
          </div>

          <p className="text-slate-500 text-sm -mt-6">
            Design personalized investor outreach, target specific investor groups, and track real-time delivery, open & click rates.
          </p>

          {/* Banner */}
          <div className="bg-[#f0fdf4] border border-[#bbf7d0] rounded-lg p-4 flex items-center justify-between">
            <div className="flex items-center gap-3 text-[#166534]">
              <CheckCircle2 className="w-5 h-5" />
              <p className="text-sm">
                <strong>Brevo queue active.</strong> Up to 300 emails are sent per UTC day; remaining recipients continue automatically.
              </p>
            </div>
            <div className="text-xs font-medium text-[#166534] flex flex-col items-end">
              <span>Native</span>
              <span>Supabase</span>
            </div>
          </div>

          {/* KPI Grid */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <MetricCard icon={<Mail className="w-5 h-5 text-slate-600"/>} title="Total Campaigns" value="0" sub="Broadcast updates" />
            <MetricCard icon={<Send className="w-5 h-5 text-blue-500"/>} title="Total Sent" value="0" sub="Sent · 0 queued" valueColor="text-blue-600" />
            <MetricCard icon={<CheckCircle2 className="w-5 h-5 text-emerald-500"/>} title="Delivered" value="0" sub="100% delivery rate" valueColor="text-emerald-600" />
            <MetricCard icon={<Eye className="w-5 h-5 text-indigo-500"/>} title="Open Rate" value="0%" sub="0 opened" valueColor="text-indigo-600" />
            <MetricCard icon={<MousePointerClick className="w-5 h-5 text-purple-500"/>} title="Click Rate" value="0%" sub="0 clicked links" valueColor="text-purple-600" />
            <MetricCard icon={<AlertCircle className="w-5 h-5 text-amber-500"/>} title="Bounces / Failed" value="0" sub="Deliverability issues" valueColor="text-amber-600" />
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col animate-in slide-in-from-right-8 duration-300">
          {/* Compose Header */}
          <div className="border-b border-slate-100 p-6 flex justify-between items-center bg-slate-50">
            <div className="flex items-center gap-4">
              <div className="bg-white p-2 rounded-md shadow-sm border border-slate-200">
                <Mail className="w-6 h-6 text-slate-700" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-slate-900">Compose Investor Campaign</h2>
                <p className="text-sm text-slate-500">Targeted outreach with Brevo delivery and dynamic CRM personalization.</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <button 
                onClick={sendCampaign}
                className="px-6 py-2 bg-slate-900 text-white rounded-md font-medium text-sm hover:bg-slate-800 shadow-sm transition-colors"
              >
                Compose
              </button>
              <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-md font-medium text-sm hover:bg-slate-50 transition-colors shadow-sm">
                <Eye className="w-4 h-4" /> Live Preview
              </button>
              <button onClick={() => setView('dashboard')} className="p-2 text-slate-400 hover:text-slate-600 transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>
          </div>

          <div className="flex flex-col lg:flex-row h-full max-h-[800px] overflow-hidden">
            {/* Left Column: Form & Editor */}
            <div className="flex-1 p-6 overflow-y-auto border-r border-slate-100">
              <div className="flex gap-6 mb-6">
                <div className="flex-1 space-y-2">
                  <label className="text-sm font-semibold text-slate-700">Campaign Name (Internal)</label>
                  <input 
                    type="text" 
                    value={campaignName}
                    onChange={e => setCampaignName(e.target.value)}
                    placeholder="e.g. Q1 Fund II Performance Note" 
                    className="w-full px-4 py-2.5 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-slate-900 outline-none transition-all"
                  />
                </div>
                <div className="flex-1 space-y-2">
                  <label className="text-sm font-semibold text-slate-700">From Sender</label>
                  <input 
                    type="text" 
                    value={sender}
                    onChange={e => setSender(e.target.value)}
                    className="w-full px-4 py-2.5 border border-slate-200 rounded-lg text-sm bg-slate-50 font-mono text-slate-600 outline-none"
                  />
                </div>
              </div>

              <div className="space-y-2 mb-6">
                <label className="text-sm font-semibold text-slate-700">Subject Line</label>
                <input 
                  type="text" 
                  value={subject}
                  onChange={e => setSubject(e.target.value)}
                  placeholder="e.g. Exclusive Update: Fund II Q1 Track Record for {{organization}}" 
                  className="w-full px-4 py-2.5 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-slate-900 outline-none transition-all"
                />
              </div>

              <div className="mb-6 p-4 border border-slate-200 rounded-lg bg-slate-50/50">
                <div className="flex justify-between items-center mb-3">
                  <span className="text-sm font-semibold text-slate-700 flex items-center gap-2">
                    ✨ Insert Personalization Tag:
                  </span>
                  <span className="text-xs text-slate-400">Click to insert at cursor</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {tags.map(t => (
                    <button 
                      key={t.tag}
                      onClick={() => insertTag(t.tag)}
                      className="px-3 py-1.5 bg-white border border-slate-200 rounded text-xs font-mono text-slate-600 hover:border-slate-400 hover:text-slate-900 transition-colors flex items-center shadow-sm"
                    >
                      {t.tag} <span className="ml-1 text-[10px] text-slate-400 font-sans">({t.label})</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-2">
                <div className="flex justify-between items-end mb-2">
                  <label className="text-sm font-semibold text-slate-700">HTML Message Body</label>
                  <div className="flex border border-slate-200 rounded-md overflow-hidden">
                    <button 
                      onClick={() => setBodyMode('source')}
                      className={`px-3 py-1 text-xs font-medium ${bodyMode === 'source' ? 'bg-slate-100 text-slate-900' : 'bg-white text-slate-500 hover:bg-slate-50'}`}
                    >
                      HTML Source
                    </button>
                    <button 
                      onClick={() => setBodyMode('rendered')}
                      className={`px-3 py-1 text-xs font-medium border-l border-slate-200 ${bodyMode === 'rendered' ? 'bg-slate-100 text-slate-900' : 'bg-white text-slate-500 hover:bg-slate-50'}`}
                    >
                      Rendered
                    </button>
                  </div>
                </div>

                {bodyMode === 'source' ? (
                  <textarea 
                    ref={bodyRef}
                    value={body}
                    onChange={e => setBody(e.target.value)}
                    className="w-full h-64 p-4 border border-slate-200 rounded-lg text-sm font-mono focus:ring-2 focus:ring-slate-900 outline-none transition-all resize-none"
                  />
                ) : (
                  <div 
                    className="w-full h-64 p-4 border border-slate-200 rounded-lg prose prose-sm max-w-none overflow-y-auto bg-white"
                    dangerouslySetInnerHTML={{ __html: body }}
                  />
                )}
              </div>
            </div>

            {/* Right Column: Filters & Audience */}
            <div className="w-full lg:w-80 bg-slate-50 p-6 overflow-y-auto flex flex-col">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-sm font-semibold text-slate-900 flex items-center gap-2">
                  <Filter className="w-4 h-4" /> Investor Group Filters
                </h3>
                <span className="px-2 py-0.5 bg-slate-200 text-slate-700 rounded-full text-xs font-medium">
                  {selectedLeads.size} Selected
                </span>
              </div>

              <div className="space-y-4 mb-6">
                <div>
                  <label className="text-xs font-medium text-slate-500 mb-1 block">Investor List</label>
                  <select className="w-full text-sm border-slate-200 rounded-md p-2 bg-white">
                    <option>All Lists</option>
                  </select>
                </div>
                <div>
                  <label className="text-xs font-medium text-slate-500 mb-1 block">Investor Type</label>
                  <select 
                    value={typeFilter}
                    onChange={(e) => setTypeFilter(e.target.value)}
                    className="w-full text-sm border-slate-200 rounded-md p-2 bg-white"
                  >
                    <option value="All Types">All Types</option>
                    {settings.investorTypes?.map((t: string) => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-medium text-slate-500 mb-1 block">Pipeline Stage</label>
                  <select 
                    value={stageFilter}
                    onChange={(e) => setStageFilter(e.target.value)}
                    className="w-full text-sm border-slate-200 rounded-md p-2 bg-white"
                  >
                    <option value="All Stages">All Stages</option>
                    {settings.leadStages?.map((s: string) => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-medium text-slate-500 mb-1 block">Fund / Client Type</label>
                  <select className="w-full text-sm border-slate-200 rounded-md p-2 bg-white">
                    <option>All Funds</option>
                  </select>
                </div>
              </div>

              <div className="flex justify-between items-center mb-3">
                <span className="text-xs text-slate-500">Matches: <strong className="text-slate-700">{filteredLeads.length}</strong> leads</span>
                <div className="flex gap-2 text-xs font-medium">
                  <button onClick={handleSelectAll} className="text-slate-900 hover:underline">Select All</button>
                  <span className="text-slate-300">·</span>
                  <button onClick={() => setSelectedLeads(new Set())} className="text-slate-500 hover:underline">Clear</button>
                </div>
              </div>

              <div className="relative mb-3">
                <Search className="w-3.5 h-3.5 absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
                <input 
                  type="text" 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Filter by name or email..."
                  className="w-full pl-8 pr-3 py-1.5 text-xs border border-slate-200 rounded-md outline-none focus:border-slate-400"
                />
              </div>

              <div className="flex-1 bg-white border border-slate-200 rounded-md overflow-y-auto">
                {filteredLeads.length === 0 ? (
                  <div className="p-4 text-center text-xs text-slate-500 mt-4">
                    No investors match the chosen group filters.
                  </div>
                ) : (
                  <ul className="divide-y divide-slate-100">
                    {filteredLeads.map(lead => (
                      <li key={lead.id} className="flex items-center gap-3 p-2.5 hover:bg-slate-50 cursor-pointer" onClick={() => toggleLead(lead.id)}>
                        <input 
                          type="checkbox" 
                          checked={selectedLeads.has(lead.id)} 
                          onChange={() => {}} // handled by li click
                          className="rounded border-slate-300 text-slate-900 focus:ring-slate-900"
                        />
                        <div className="overflow-hidden">
                          <p className="text-xs font-medium text-slate-900 truncate">{lead.firstName} {lead.lastName}</p>
                          <p className="text-[10px] text-slate-500 truncate">{lead.email || lead.organization}</p>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function MetricCard({ icon, title, value, sub, valueColor = "text-slate-900" }: { icon: any, title: string, value: string, sub: string, valueColor?: string }) {
  return (
    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col justify-between">
      <div className="flex items-center gap-2 mb-4">
        {icon}
        <span className="text-sm font-medium text-slate-600">{title}</span>
      </div>
      <div>
        <h3 className={`text-3xl font-bold mb-1 ${valueColor}`}>{value}</h3>
        <p className="text-xs text-slate-500">{sub}</p>
      </div>
    </div>
  );
}

