          />
        </div>
        <div className="relative" ref={filterMenuRef}>
          <button 
            onClick={() => setShowFilterMenu(!showFilterMenu)}
            className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 rounded-md hover:bg-slate-50"
          >
            <Filter className="w-4 h-4" /> {stageFilter === 'All' ? 'Filter' : stageFilter}
          </button>

          {showFilterMenu && (
            <div className="absolute right-0 top-full mt-2 w-48 bg-white border border-slate-200 rounded-lg shadow-xl z-20 py-2">
              <div className="px-4 py-2">
                <h4 className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider mb-2">Filter by Stage</h4>
                <div className="space-y-1">
                  <button 
                    onClick={() => { setStageFilter('All'); setShowFilterMenu(false); }}
                    className={`w-full text-left px-2 py-1.5 text-sm rounded-md hover:bg-slate-50 ${stageFilter === 'All' ? 'font-bold text-blue-600' : 'text-slate-600'}`}
                  >
                    All Stages
                  </button>
                  {settings?.leadStages?.map((stage: string) => (
                    <button 
                      key={stage}
                      onClick={() => { setStageFilter(stage); setShowFilterMenu(false); }}
                      className={`w-full text-left px-2 py-1.5 text-sm rounded-md hover:bg-slate-50 ${stageFilter === stage ? 'font-bold text-blue-600' : 'text-slate-600'}`}
                    >
                      {stage}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Table */}
      <div className={`bg-white border border-slate-200 rounded-xl shadow-sm flex-1 overflow-hidden flex flex-col ${isExcelMode ? 'ring-2 ring-blue-500/20' : ''}`}>
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-left text-sm whitespace-nowrap">
            <thead className="bg-slate-50 border-b border-slate-200 text-slate-500 text-xs font-semibold sticky top-0 z-10">
              <tr>
                <th className="px-6 py-4 w-10">
                  <input type="checkbox" className="rounded border-slate-300 text-blue-600 focus:ring-blue-500" />
                </th>
                {columns.filter(c => c.visible).map(c => (
                  <th key={c.id} className="px-6 py-4">{c.label}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan={columns.filter(c => c.visible).length + 1} className="px-6 py-8 text-center text-slate-500">Loading leads...</td>
                </tr>
              ) : filteredLeads.length === 0 ? (
                <tr>
                  <td colSpan={columns.filter(c => c.visible).length + 1} className="px-6 py-12 text-center text-slate-500">
                    No leads found matching criteria.
                  </td>
                </tr>
              ) : (
                filteredLeads.map((lead, rowIndex) => (
                  <tr 
                    key={lead.id} 
                    onClick={() => handleRowClick(lead)} 
                    className={`${isExcelMode ? 'bg-white' : 'hover:bg-slate-50 transition-colors cursor-pointer'}`}
                  >
                    <td className="px-6 py-2" onClick={e => e.stopPropagation()}>
                      <input type="checkbox" className="rounded border-slate-300 text-blue-600 focus:ring-blue-500" />
                    </td>
                    {columns.filter(c => c.visible).map((c, colIndex) => (
                      <td key={c.id} className={`px-0 py-0 ${isExcelMode ? 'border-r border-slate-100 last:border-r-0' : 'px-6 py-4'}`}>
                        {isExcelMode ? renderExcelModeCell(lead, c, rowIndex, colIndex) : renderCell(lead, c.id)}
                      </td>
                    ))}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
        {isExcelMode && (
          <div className="p-2 border-t border-slate-200 bg-slate-50">
            <button 
              onClick={handleAddExcelRow}
              className="flex items-center gap-2 px-3 py-1.5 text-xs font-medium text-slate-600 hover:text-slate-900 hover:bg-slate-200 rounded transition-colors"
            >
              <Plus className="w-3.5 h-3.5" /> Add Row
            </button>
          </div>
        )}
      </div>

      <AddLeadModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSuccess={fetchData} 
      />

      <LeadSlideOver
        isOpen={isSlideOverOpen}
        onClose={() => setIsSlideOverOpen(false)}
        lead={selectedLead}
        onSuccess={fetchData}
        settings={settings}
      />
    </div>
  );
}

