import React, { useRef, useEffect } from 'react';

interface RichTextEditorProps {
  value: string;
  onChange: (val: string) => void;
  tags: { tag: string; label: string }[];
}

export function RichTextEditor({ value, onChange, tags }: RichTextEditorProps) {
  const editorRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (editorRef.current && !editorRef.current.innerHTML) {
      editorRef.current.innerHTML = value;
    }
  }, [value]);

  const exec = (cmd: string, val: string | undefined = undefined) => {
    document.execCommand(cmd, false, val);
    editorRef.current?.focus();
    onChange(editorRef.current?.innerHTML || '');
  };

  return (
    <div className="border border-slate-200 rounded-xl flex flex-col bg-white shadow-sm overflow-hidden h-full">
      <div className="flex flex-wrap items-center gap-1 p-2 border-b border-slate-100 bg-slate-50 sticky top-0 z-10">
        <button onClick={() => exec('bold')} className="w-8 h-8 flex items-center justify-center hover:bg-slate-200 rounded text-slate-700 font-bold transition-all" title="Bold">B</button>
        <button onClick={() => exec('italic')} className="w-8 h-8 flex items-center justify-center hover:bg-slate-200 rounded text-slate-700 italic font-serif transition-all" title="Italic">I</button>
        <button onClick={() => exec('underline')} className="w-8 h-8 flex items-center justify-center hover:bg-slate-200 rounded text-slate-700 underline transition-all" title="Underline">U</button>
        <div className="w-px h-5 bg-slate-300 mx-1" />
        <button onClick={() => exec('insertUnorderedList')} className="px-3 h-8 flex items-center justify-center hover:bg-slate-200 rounded text-slate-700 text-xs font-medium transition-all" title="Bullet List">List</button>
        <button onClick={() => { const url = prompt('Enter URL (e.g. https://google.com)'); if (url) exec('createLink', url); }} className="px-3 h-8 flex items-center justify-center hover:bg-slate-200 rounded text-slate-700 text-xs font-medium transition-all" title="Link">Link</button>
        <div className="w-px h-5 bg-slate-300 mx-1" />
        <select onChange={(e) => { if(e.target.value) exec('insertText', e.target.value); e.target.value = ''; }} className="h-8 px-2 text-xs border border-slate-200 rounded bg-white text-slate-600 outline-none hover:border-slate-300 cursor-pointer">
          <option value="">✨ Insert Tag...</option>
          {tags.map(t => (<option key={t.tag} value={t.tag}>{t.label}</option>))}
        </select>
      </div>
      <div 
        ref={editorRef} 
        contentEditable 
        onInput={() => onChange(editorRef.current?.innerHTML || '')} 
        className="p-6 flex-1 min-h-[300px] outline-none prose prose-sm prose-slate max-w-none focus:bg-slate-50/30 transition-colors"
      />
    </div>
  );
}

import React, { useState } from 'react';
import { RichTextEditor } from './RichTextEditor';
import { Lead } from '@/hooks/useLeads';
import { GlobalSettings } from '@/hooks/useSettings';
import { Mail, Send, Eye, Code, X, AlertCircle } from 'lucide-react';
import toast from 'react-hot-toast';

interface EmailComposerProps {
  onClose: () => void;
  selectedLeads: Set<string>;
  leadsData: Lead[];
  settings: GlobalSettings | null;
  recordCampaign: (data: any) => Promise<string>;
}

const TAGS = [
  { tag: "{{first_name}}", label: "First Name" },
  { tag: "{{last_name}}", label: "Last Name" },
  { tag: "{{organization}}", label: "Organization" },
  { tag: "{{email}}", label: "Email" },
  { tag: "{{investor_type}}", label: "Investor Type" },
  { tag: "{{lead_stage}}", label: "Lead Stage" },
];

export function EmailComposer({ onClose, selectedLeads, leadsData, settings, recordCampaign }: EmailComposerProps) {
  const [campaignName, setCampaignName] = useState("");
  const [senderName, setSenderName] = useState("Investor Relations");
  const [senderEmail, setSenderEmail] = useState("info@moneystories.in");
  const [subject, setSubject] = useState("");
  const [body, setBody] = useState("<p>Dear {{first_name}},</p><p><br></p><p>We have a new update for <strong>{{organization}}</strong>.</p><p><br></p><p>Warm regards,<br>The Team</p>");

  const [isSending, setIsSending] = useState(false);
  const [progress, setProgress] = useState({ current: 0, total: 0 });

  const recipients = leadsData.filter(l => selectedLeads.has(l.id));
  const previewLead = recipients[0] || { firstName: 'John', lastName: 'Doe', organization: 'Acme Corp', email: 'john@example.com', investorType: 'Angel', leadStage: 'Cold' };

  // Generate live preview
  let previewHtml = body;
  TAGS.forEach(t => {
    const key = t.tag.replace(/[{}]/g, '');
    const camelKey = key.replace(/_([a-z])/g, g => g[1].toUpperCase());
    previewHtml = previewHtml.replace(new RegExp(t.tag, 'g'), previewLead[camelKey as keyof typeof previewLead] || t.label);
  });

  const handleSend = async () => {
    if (!settings?.emailConfig?.brevoApiKey) {
      return toast.error("Brevo API Key is missing in Global Settings.");
    }
    if (!campaignName || !subject || !body) {
      return toast.error("Please fill in all fields.");
    }
    if (recipients.length === 0) {
      return toast.error("No recipients selected.");
    }

    setIsSending(true);
    setProgress({ current: 0, total: recipients.length });

    try {
      // We will batch in chunks of 50 to avoid Brevo payload limits
      const chunkSize = 50;
      let successCount = 0;

      for (let i = 0; i < recipients.length; i += chunkSize) {
        const chunk = recipients.slice(i, i + chunkSize);

        // Convert our custom tags {{first_name}} to Brevo params {{params.first_name}}
        let brevoHtml = body;
        TAGS.forEach(t => {
          const key = t.tag.replace(/[{}]/g, '');
          brevoHtml = brevoHtml.replace(new RegExp(t.tag, 'g'), `{{params.${key}}}`);
        });

        const messageVersions = chunk.map(lead => {
          return {
            to: [{ email: lead.email, name: `${lead.firstName} ${lead.lastName}` }],
            params: {
              first_name: lead.firstName || '',
              last_name: lead.lastName || '',
              organization: lead.organization || '',
              email: lead.email || '',
              investor_type: lead.investorType || '',
              lead_stage: lead.leadStage || ''
            }
          };
        });

        const payload = {
          sender: { name: senderName, email: senderEmail },
          subject: subject,
          htmlContent: brevoHtml,
          messageVersions: messageVersions
        };

        const res = await fetch('https://api.brevo.com/v3/smtp/email', {
          method: 'POST',
          headers: {
            'api-key': settings.emailConfig.brevoApiKey,
            'Content-Type': 'application/json',
            'accept': 'application/json'
          },
          body: JSON.stringify(payload)
        });

        if (!res.ok) {
          const errorData = await res.json().catch(() => null);
          console.error("Brevo API Error:", errorData);
          throw new Error(`Brevo API Error: ${res.statusText}`);
        }

        successCount += chunk.length;
        setProgress({ current: successCount, total: recipients.length });
      }

      await recordCampaign({
        campaignName,
        subject,
        sender: `${senderName} <${senderEmail}>`,
        recipientIds: recipients.map(r => r.id),
        status: 'sent',
        successCount
      });

      toast.success(`Successfully dispatched to ${successCount} recipients!`);
      onClose();
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || "Failed to send campaign");

      await recordCampaign({
        campaignName,
        subject,
        sender: `${senderName} <${senderEmail}>`,
        recipientIds: recipients.map(r => r.id),
        status: 'failed',
        successCount: progress.current
      });
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col h-[calc(100vh-6rem)] animate-in fade-in zoom-in-95 duration-200 fixed inset-8 z-50">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-slate-100 bg-slate-50 shrink-0">
        <div className="flex items-center gap-3">
          <div className="bg-white p-2 rounded shadow-sm border border-slate-200">
            <Mail className="w-5 h-5 text-slate-700" />
          </div>
          <div>
            <h2 className="text-lg font-bold text-slate-900 leading-tight">Composer</h2>
            <p className="text-xs text-slate-500">Sending to {recipients.length} recipients</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 transition-colors rounded hover:bg-slate-200"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Split Pane */}
      <div className="flex flex-1 overflow-hidden">
        {/* Left: Editor */}
        <div className="w-1/2 flex flex-col border-r border-slate-100 bg-white overflow-y-auto p-6 space-y-6">
          <div className="space-y-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Campaign Name (Internal)</label>
              <input 
                type="text" 
                value={campaignName} onChange={e => setCampaignName(e.target.value)}
                placeholder="e.g. Q1 Newsletter"
                className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm outline-none focus:border-slate-900"
              />
            </div>
            <div className="flex gap-4">
              <div className="flex-1">
                <label className="block text-xs font-semibold text-slate-700 mb-1">Sender Name</label>
                <input 
                  type="text" 
                  value={senderName} onChange={e => setSenderName(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm outline-none focus:border-slate-900"
                />
              </div>
              <div className="flex-1">
                <label className="block text-xs font-semibold text-slate-700 mb-1">Sender Email</label>
                <input 
                  type="email" 
                  value={senderEmail} onChange={e => setSenderEmail(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm outline-none focus:border-slate-900"
                />
              </div>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Subject Line</label>
              <input 
                type="text" 
                value={subject} onChange={e => setSubject(e.target.value)}
                placeholder="Exciting updates for {{organization}}"
                className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm outline-none focus:border-slate-900"
              />
            </div>
          </div>

          <div className="flex-1 flex flex-col min-h-[300px]">
            <label className="block text-xs font-semibold text-slate-700 mb-1">Email Body</label>
            <RichTextEditor value={body} onChange={setBody} tags={TAGS} />
          </div>
        </div>

        {/* Right: Live Preview */}
        <div className="w-1/2 flex flex-col bg-slate-50 overflow-hidden">
          <div className="p-4 border-b border-slate-200 bg-slate-100 flex items-center gap-2 shrink-0">
            <Eye className="w-4 h-4 text-slate-500" />
            <span className="text-xs font-semibold text-slate-600 uppercase tracking-wider">Live Preview</span>
            <span className="text-xs text-slate-400 ml-auto">Previewing as: {previewLead?.firstName || 'Unknown'}</span>
          </div>

          <div className="flex-1 overflow-y-auto p-8 flex justify-center">
            <div className="w-full max-w-lg bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col overflow-hidden self-start">
              <div className="px-4 py-3 border-b border-slate-100 bg-slate-50/50 space-y-1">
                <div className="text-xs text-slate-500"><span className="font-semibold text-slate-700">From:</span> {senderName} &lt;{senderEmail}&gt;</div>
                <div className="text-xs text-slate-500"><span className="font-semibold text-slate-700">To:</span> {previewLead?.firstName} &lt;{previewLead?.email}&gt;</div>
                <div className="text-sm font-bold text-slate-900 pt-2">{subject.replace(/{{organization}}/g, previewLead?.organization || 'Organization')}</div>
              </div>
              <div 
                className="p-6 prose prose-sm prose-slate max-w-none"
                dangerouslySetInnerHTML={{ __html: previewHtml }}
              />
            </div>
          </div>

          {/* Action Bar */}
          <div className="p-6 border-t border-slate-200 bg-white flex items-center justify-between shrink-0">
            <div className="text-xs text-slate-500 flex items-center gap-2">
              {!settings?.emailConfig?.brevoApiKey && (
                <span className="text-red-500 flex items-center gap-1"><AlertCircle className="w-4 h-4" /> Brevo API Key missing</span>
              )}
            </div>
            <button 
              onClick={handleSend}
              disabled={isSending || !settings?.emailConfig?.brevoApiKey}
              className="px-8 py-3 bg-slate-900 text-white rounded-xl font-bold text-sm hover:bg-slate-800 disabled:opacity-50 transition-all shadow-xl flex items-center gap-2"
            >
              {isSending ? (
                `Sending... ${progress.current}/${progress.total}`
              ) : (
                <><Send className="w-4 h-4" /> Dispatch Campaign</>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useLeads } from "@/hooks/useLeads";
import { useEmailQueue } from "@/hooks/useEmailQueue";
import { useSettings } from "@/hooks/useSettings";
import { EmailComposer } from "@/components/email/EmailComposer";
import { Mail, Send, CheckCircle2, Eye, MousePointerClick, AlertCircle, Settings2, Plus, Clock } from "lucide-react";
import { format } from "date-fns";
import { useRouter } from "next/navigation";

export default function EmailModule() {
  const router = useRouter();
  const { leads, loading: leadsLoading } = useLeads();
  const { campaigns, loading: queueLoading, recordCampaign } = useEmailQueue();
  const { settings } = useSettings();

  const [isComposing, setIsComposing] = useState(false);
  const [selectedLeads, setSelectedLeads] = useState<Set<string>>(new Set());

  // Filter state for dashboard
  const [stageFilter, setStageFilter] = useState("All");
  const [typeFilter, setTypeFilter] = useState("All");
  const [searchQuery, setSearchQuery] = useState("");

  const filteredLeads = leads.filter(lead => {
    const matchesStage = stageFilter === "All" || lead.leadStage === stageFilter;
    const matchesType = typeFilter === "All" || lead.investorType === typeFilter;
    const matchesSearch = !searchQuery || 
      `${lead.firstName} ${lead.lastName} ${lead.email} ${lead.organization}`
      .toLowerCase().includes(searchQuery.toLowerCase());
    return matchesStage && matchesType && matchesSearch;
  });

  const handleSelectAll = () => {
    if (selectedLeads.size === filteredLeads.length) {
      setSelectedLeads(new Set());
    } else {
      setSelectedLeads(new Set(filteredLeads.map(l => l.id)));
    }
  };

  const toggleLead = (id: string) => {
    const newSet = new Set(selectedLeads);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedLeads(newSet);
  };

  const totalCampaigns = campaigns.length;
  const sentCampaigns = campaigns.filter(c => c.status === 'sent').length;
  const failedCampaigns = campaigns.filter(c => c.status === 'failed').length;
  const sentRecipients = campaigns.filter(c => c.status === 'sent').reduce((acc, c) => acc + (c.successCount || 0), 0);

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <h1 className="text-2xl font-bold text-slate-900">Email Broadcasts</h1>
          <span className="px-2.5 py-0.5 rounded-md border border-slate-200 text-xs font-medium text-slate-600 bg-white shadow-sm">
            Brevo Engine Active
          </span>
        </div>
        <div className="flex gap-3">
          <button onClick={() => router.push('/settings')} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-md font-medium text-sm hover:bg-slate-50 transition-colors shadow-sm">
            <Settings2 className="w-4 h-4" /> Config
          </button>
          <button 
            onClick={() => setIsComposing(true)}
            className="flex items-center gap-2 px-4 py-2 bg-[#1a1a1a] text-white rounded-md font-medium text-sm hover:bg-black transition-colors shadow-sm"
          >
            <Plus className="w-4 h-4" /> New Campaign
          </button>
        </div>
      </div>

      {/* KPI Grid */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white border border-slate-200 p-5 rounded-xl shadow-sm">
          <div className="flex items-center justify-between mb-4"><Mail className="w-5 h-5 text-slate-400"/><span className="text-xs font-semibold text-slate-500 uppercase">Total Campaigns</span></div>
          <div className="text-3xl font-bold text-slate-900">{totalCampaigns}</div>
        </div>
        <div className="bg-white border border-slate-200 p-5 rounded-xl shadow-sm">
          <div className="flex items-center justify-between mb-4"><Send className="w-5 h-5 text-blue-500"/><span className="text-xs font-semibold text-slate-500 uppercase">Total Delivered</span></div>
          <div className="text-3xl font-bold text-slate-900">{sentRecipients}</div>
        </div>
        <div className="bg-white border border-slate-200 p-5 rounded-xl shadow-sm">
          <div className="flex items-center justify-between mb-4"><Eye className="w-5 h-5 text-emerald-500"/><span className="text-xs font-semibold text-slate-500 uppercase">Open Rate</span></div>
          <div className="text-3xl font-bold text-slate-900">--%</div>
        </div>
        <div className="bg-white border border-slate-200 p-5 rounded-xl shadow-sm">
          <div className="flex items-center justify-between mb-4"><AlertCircle className="w-5 h-5 text-amber-500"/><span className="text-xs font-semibold text-slate-500 uppercase">Failed</span></div>
          <div className="text-3xl font-bold text-slate-900">{failedCampaigns}</div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left: Audience Selection (Takes up 1/3) */}
        <div className="lg:col-span-1 bg-white border border-slate-200 rounded-xl shadow-sm flex flex-col h-[600px]">
          <div className="p-4 border-b border-slate-100 bg-slate-50">
            <h3 className="font-semibold text-slate-900">Audience Selection</h3>
            <p className="text-xs text-slate-500 mb-4">Select leads for your next campaign</p>

            <input 
              type="text" 
              placeholder="Search leads..." 
              value={searchQuery} onChange={e => setSearchQuery(e.target.value)}
              className="w-full text-sm px-3 py-2 border border-slate-200 rounded-md mb-2 outline-none focus:border-slate-400"
            />
            <div className="flex gap-2">
              <select value={stageFilter} onChange={e => setStageFilter(e.target.value)} className="flex-1 text-xs px-2 py-1.5 border border-slate-200 rounded outline-none bg-white">
                <option value="All">All Stages</option>
                {settings.leadStages?.map((s: string) => <option key={s} value={s}>{s}</option>)}
              </select>
              <select value={typeFilter} onChange={e => setTypeFilter(e.target.value)} className="flex-1 text-xs px-2 py-1.5 border border-slate-200 rounded outline-none bg-white">
                <option value="All">All Types</option>
                {settings.investorTypes?.map((t: string) => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
          </div>
          <div className="p-2 border-b border-slate-100 flex justify-between items-center bg-white">
            <span className="text-xs font-medium text-slate-600">{selectedLeads.size} selected</span>
            <button onClick={handleSelectAll} className="text-xs font-semibold text-slate-900 hover:underline">Select All Filtered</button>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {leadsLoading ? (
              <div className="p-4 text-center text-xs text-slate-500">Loading leads...</div>
            ) : filteredLeads.length === 0 ? (
              <div className="p-4 text-center text-xs text-slate-500">No leads match filters.</div>
            ) : (
              filteredLeads.map(lead => (
                <div 
                  key={lead.id} 
                  onClick={() => toggleLead(lead.id)}
                  className={`flex items-center gap-3 p-2 rounded cursor-pointer transition-colors ${selectedLeads.has(lead.id) ? 'bg-slate-100' : 'hover:bg-slate-50'}`}
                >
                  <input type="checkbox" checked={selectedLeads.has(lead.id)} readOnly className="rounded border-slate-300 text-slate-900 focus:ring-slate-900" />
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium text-slate-900 truncate">{lead.firstName} {lead.lastName}</p>
                    <p className="text-xs text-slate-500 truncate">{lead.organization}</p>
                  </div>
                </div>
              ))
            )}
          </div>
          <div className="p-4 border-t border-slate-100 bg-slate-50">
            <button 
              onClick={() => setIsComposing(true)}
              disabled={selectedLeads.size === 0}
              className="w-full py-2 bg-slate-900 text-white rounded-lg font-medium text-sm hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-sm"
            >
              Compose for {selectedLeads.size} Recipients
            </button>
          </div>
        </div>

        {/* Right: Campaign History (Takes up 2/3) */}
        <div className="lg:col-span-2 bg-white border border-slate-200 rounded-xl shadow-sm flex flex-col h-[600px]">
          <div className="px-6 py-4 border-b border-slate-100 flex items-center gap-2 bg-slate-50">
            <Clock className="w-4 h-4 text-slate-500" />
            <h3 className="font-semibold text-slate-900">Campaign History</h3>
          </div>
          <div className="flex-1 overflow-y-auto">
            <table className="w-full text-left text-sm whitespace-nowrap">
              <thead className="bg-white border-b border-slate-100 text-slate-500 text-xs font-semibold uppercase tracking-wider sticky top-0">
                <tr>
                  <th className="px-6 py-4">Campaign Name</th>
                  <th className="px-6 py-4">Subject</th>
                  <th className="px-6 py-4">Status</th>
                  <th className="px-6 py-4">Date Sent</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {queueLoading ? (
                  <tr><td colSpan={4} className="px-6 py-8 text-center text-slate-500">Loading...</td></tr>
                ) : campaigns.length === 0 ? (
                  <tr><td colSpan={4} className="px-6 py-8 text-center text-slate-500">No campaigns sent yet.</td></tr>
                ) : (
                  campaigns.map(c => (
                    <tr key={c.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4 font-medium text-slate-900">{c.name}</td>
                      <td className="px-6 py-4 text-slate-600 max-w-[200px] truncate">{c.subject}</td>
                      <td className="px-6 py-4">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium uppercase tracking-wider ${
                          c.status === 'sent' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 
                          c.status === 'failed' ? 'bg-red-50 text-red-700 border border-red-200' :
                          'bg-amber-50 text-amber-700 border border-amber-200'
                        }`}>
                          {c.status} {c.successCount ? `(${c.successCount})` : ''}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-slate-500">
                        {c.createdAt ? format(c.createdAt.toDate(), "MMM d, yyyy h:mm a") : "-"}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Fullscreen Composer Modal overlaying everything */}
      {isComposing && (
        <>
          <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-40 transition-all" />
          <EmailComposer 
            onClose={() => setIsComposing(false)}
            selectedLeads={selectedLeads}
            leadsData={leads}
            settings={settings}
            recordCampaign={recordCampaign}
          />
        </>
      )}
    </div>
  );
}

